Done. Stayed on `existing-feature` in the assigned worktree throughout; never touched the sibling `coding-agent-workdir` or `main`, created no branches, and did not push.

## `src/slugify.js`

```js
function slugify(title) {
  if (typeof title !== 'string') {
    return '';
  }

  return title
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

module.exports = { slugify };
```

Trimming falls out of the leading/trailing hyphen strip, so no separate `.trim()` is needed — surrounding whitespace becomes a hyphen that is then removed.

## `src/slugify.test.js`

```js
const test = require('node:test');
const assert = require('node:assert/strict');

const { slugify } = require('./slugify');

test('slugifies a plain title', () => {
  assert.equal(slugify('hello world'), 'hello-world');
});

test('lowercases mixed case', () => {
  assert.equal(slugify('Hello World'), 'hello-world');
});

test('collapses punctuation and symbols into single hyphens', () => {
  assert.equal(slugify('Hello, World! & Friends?'), 'hello-world-friends');
});

test('collapses multiple, leading, and trailing spaces', () => {
  assert.equal(slugify('  Hello   World  '), 'hello-world');
});

test('leaves an already-slugged string unchanged', () => {
  assert.equal(slugify('hello-world'), 'hello-world');
});

test('returns an empty string for an empty input', () => {
  assert.equal(slugify(''), '');
});

test('returns an empty string for a non-string input', () => {
  assert.equal(slugify(null), '');
  assert.equal(slugify(undefined), '');
  assert.equal(slugify(42), '');
});
```

